```javascript
/**
 * Debounce with an injectable fake clock.
 *
 * @param {Function} fn - The function to debounce.
 * @param {number} wait_ms - Wait time in milliseconds.
 * @param {{ now: () => number }} clock - Time source (e.g., a fake clock).
 * @returns {Function} Debounced function.
 */
function debounce(fn, wait_ms, clock) {
  let timer = null;
  let lastArgs = null;
  let lastThis = null;

  return function debounced(...args) {
    lastArgs = args;
    lastThis = this;

    if (timer === null) {
      const start = clock.now();
      timer = setTimeout(() => {
        timer = null;
        fn.apply(lastThis, lastArgs);
      }, wait_ms);
    } else {
      // Reschedule relative to the *current* time so repeated
      // calls within the window keep pushing the deadline out.
      const remaining = wait_ms - (clock.now() - start);
      clearTimeout(timer);
      timer = setTimeout(() => {
        timer = null;
        fn.apply(lastThis, lastArgs);
      }, remaining);
    }
  };
}
```

